from datetime import date, time

from sqlalchemy import Date, Float, ForeignKey, Index, Integer, String, Time
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import Mapped, mapped_column, relationship

from app.models.base import Base, TimestampMixin, generate_uuid


class Meal(Base, TimestampMixin):
    """Whatever the user ate at one time: no breakfast/lunch/dinner slots."""

    __tablename__ = "meals"
    __table_args__ = (Index("ix_meals_user_date", "user_id", "eaten_on"),)

    # Generated by the client, so saving a meal is an idempotent upsert.
    id: Mapped[str] = mapped_column(String(36), primary_key=True)
    user_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("users.id", ondelete="CASCADE"), nullable=False
    )
    # The user's local date and wall-clock time.
    eaten_on: Mapped[date] = mapped_column(Date, nullable=False)
    eaten_at: Mapped[time] = mapped_column(Time, nullable=False)
    name: Mapped[str | None] = mapped_column(String(255), nullable=True)
    # "auto": the name comes from Claude and follows the items; "user": renamed.
    name_source: Mapped[str] = mapped_column(String(8), nullable=False, default="auto")
    # Claude's grouping of the items for the timeline card: [{text, grams}].
    summary: Mapped[list | None] = mapped_column(JSONB, nullable=True)
    # Fingerprint of the items the summary (and an auto name) describes.
    summary_key: Mapped[str | None] = mapped_column(String(64), nullable=True)

    items: Mapped[list["MealItem"]] = relationship(
        back_populates="meal",
        order_by="MealItem.position",
        cascade="all, delete-orphan",
        lazy="selectin",
    )


class MealItem(Base):
    """One food in a meal. Name and macros are copied from the food, so the
    item survives the food being edited or deleted."""

    __tablename__ = "meal_items"

    id: Mapped[str] = mapped_column(String(36), primary_key=True, default=generate_uuid)
    meal_id: Mapped[str] = mapped_column(
        String(36), ForeignKey("meals.id", ondelete="CASCADE"), nullable=False, index=True
    )
    position: Mapped[int] = mapped_column(Integer, nullable=False)
    food_item_id: Mapped[str | None] = mapped_column(
        String(36), ForeignKey("food_items.id", ondelete="SET NULL"), nullable=True, index=True
    )
    name: Mapped[str] = mapped_column(String(255), nullable=False)
    # How the amount was entered: unit_quantity of unit_name (NULL = grams).
    unit_name: Mapped[str | None] = mapped_column(String(50), nullable=True)
    unit_quantity: Mapped[float | None] = mapped_column(Float, nullable=True)
    quantity_g: Mapped[float | None] = mapped_column(Float, nullable=True)
    kcal: Mapped[float] = mapped_column(Float, nullable=False)
    protein_g: Mapped[float] = mapped_column(Float, nullable=False)
    carbs_g: Mapped[float] = mapped_column(Float, nullable=False)
    fat_g: Mapped[float] = mapped_column(Float, nullable=False)

    meal: Mapped[Meal] = relationship(back_populates="items")
